    {
      "card_ids": ["C44"],
      "claim": "In patients with histologically proven cirrhosis, labetalol oral bioavailability was 63 ± 7%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "A 75 mg sustained-release phenylpropanolamine tablet in healthy male volunteers had an absolute bioavailability of 61.9 ± 5.9%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Terodiline absolute bioavailability in healthy volunteers ranged from 64% to 105% with a mean of 92%, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules with numeric bioavailability values are at or above 20%, with most substantially above the threshold; no affirmative sub-20% evidence was supplied.",
  "evidence_gaps": [
    "Dextromoramide evidence is qualitative ('good') and lacks a numeric F value.",
    "Some records report systemic availability or unspecified bioavailability type rather than explicitly absolute oral bioavailability, but their numeric values remain above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

